@startuml

class Song {
  + Title : string
  + Year : int
  + Length : double
  + Genre : string
}

class Artist {
  + Name : string
  + DateOfBirth : date
  + WebsiteURL : string
}

abstract class User {
  + ID : int
  + Name : string
  + Address : string
}

class RegularUser {
}

class BusinessUser {
  + VATNumber : string
}

class Single {
}

class Hit {
  + TrackNumber : int
}

class Album {
  + AlbumName : string
}

class Suggestion {
}

Single --|> Song
Hit --|> Song

User "1" -- "1" Artist : belongsTo
BusinessUser "1" -- "*" Single : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" Hit
RegularUser "1" -- "*" Suggestion : receives
RegularUser "1" -- "*" Suggestion : suggests
User --|> RegularUser
User --|> BusinessUser

@enduml

